 async function execute(
   command: string,
   args: string[],
   signal: AbortSignal,
   timeoutMs: number,
   cwd?: string,
 ): Promise<string> {
   cancelled(signal);
   return new Promise((resolve, reject) => {
     const child = spawn(command, args, {
       shell: false,
       windowsHide: true,
       cwd,
       env: localEnvironment(),
       stdio: ["ignore", "pipe", "pipe"],
     });
     let stdout = "",
       bytes = 0,
       error: ProviderError | undefined;
     const stop = (reason: ProviderError) => {
       error ??= reason;
       child.kill("SIGKILL");
     };
     const onAbort = () =>
       stop(new ProviderError("cancelled", "Local document conversion cancelled."));
     const timer = setTimeout(
       () => stop(new ProviderError("limit_reached", "Local document conversion timed out.")),
       timeoutMs,
     );
     signal.addEventListener("abort", onAbort, { once: true });
     if (signal.aborted) onAbort();
     child.stdout.on("data", (chunk: Buffer) => {
       bytes += chunk.length;
       if (bytes > 1024 * 1024)
         stop(new ProviderError("limit_reached", "Local parser output exceeds limit."));
       else stdout += chunk.toString("utf8");
     });
     child.stderr.on("data", (chunk: Buffer) => {
       bytes += chunk.length;
       if (bytes > 1024 * 1024)
         stop(new ProviderError("limit_reached", "Local parser output exceeds limit."));
     });
     const clean = () => {
       clearTimeout(timer);
       signal.removeEventListener("abort", onAbort);
     };
     child.once("error", () => {
       clean();
       reject(error ?? new ProviderError("unsupported", UNSUPPORTED));
     });
     child.once("close", (code) => {
       clean();
       if (error) reject(error);
       else if (code !== 0)
         reject(
           new ProviderError(
             "unsupported",
             "Docling local conversion failed; check packaged models. No cloud fallback.",
           ),
         );
       else resolve(stdout);
     });
   });
