     if (
       ![
         "--to",
         "--output",
         "--page-range",
         "--document-timeout",
         "--enable-remote-services",
         "--allow-external-plugins",
         "--artifacts-path",
         "--ocr",
         "--image-export-mode",
         "--abort-on-error",
