    95	/** Bound both item count and prompt length; never truncate evidence silently. */
    96	export function batches<T>(items: T[], payload: (batch: T[]) => unknown): T[][] {
    97	  const result: T[][] = [];
    98	  let current: T[] = [];
    99	  for (const item of items) {
   100	    const next = [...current, item];
   101	    if (next.length > 20 || JSON.stringify(payload(next)).length > 96_000) {
   102	      if (current.length) result.push(current);
   103	      current = [item];
   104	      if (JSON.stringify(payload(current)).length > 96_000) {
   105	        throw new Error(
   106	          "AI Splitter item and evidence exceed 96,000 prompt characters; reduce upstream item size.",
   107	        );
   108	      }
   109	    } else current = next;
   110	  }
   111	  if (current.length) result.push(current);
   112	  return result;
   113	}
