   115	export async function generate<T>(ctx: BlockContext, request: LlmObjectRequest<T>) {
   116	  ctx.signal.throwIfAborted();
   117	  let listener: () => void = () => {};
   118	  const aborted = new Promise<never>((_, reject) => {
   119	    listener = () => reject(ctx.signal.reason);
   120	    ctx.signal.addEventListener("abort", listener, { once: true });
   121	  });
   122	  try {
   123	    const result = await Promise.race([
   124	      ctx.llm.generateObject({ ...request, signal: ctx.signal }),
   125	      aborted,
   126	    ]);
   127	    ctx.signal.throwIfAborted();
   128	    return {
   129	      object: request.schema.parse(result.object),
   130	      model: z.string().min(1).parse(result.model),
   131	    };
   132	  } finally {
   133	    ctx.signal.removeEventListener("abort", listener);
   134	  }
   135	}

