    59	/**
    60	 * Dependency closure. Supporting context may occur on several branches; primary items never do.
    61	 * For requirements, themes connected to cited findings are contextual clusters, including siblings.
    62	 * Missing referenced entities remain missing and are reported, never fabricated or removed from IDs.
    63	 */
    64	export function evidenceIndex(input: PipelineData, log: (message: string) => void) {
    65	  const maps = {
    66	    sources: new Map(input.sources.map((v) => [v.id, v])),
    67	    records: new Map(input.records.map((v) => [v.id, v])),
    68	    findings: new Map(input.findings.map((v) => [v.id, v])),
    69	    themes: new Map(input.themes.map((v) => [v.id, v])),
    70	    requirements: new Map(input.requirements.map((v) => [v.id, v])),
    71	  };
    72	  const positions = new Map(
    73	    DATA_KEYS.flatMap((key) => input[key].map((item, index) => [item.id, index] as const)),
    74	  );
    75	  function selected<T extends { id: string }>(map: Map<string, T>, ids: Set<string>): T[] {
    76	    return [...ids]
    77	      .map((id) => map.get(id)!)
