    85	      ids.add(theme.id);
    86	      themesByFinding.set(findingId, ids);
    87	    }
    88	  }
    89	  for (const finding of input.findings) {
    90	    if (!finding.themeId) continue;
    91	    const ids = findingsByTheme.get(finding.themeId) ?? new Set<string>();
    92	    ids.add(finding.id);
    93	    findingsByTheme.set(finding.themeId, ids);
    94	  }
