   107	        sources: selected(maps.sources, membership.sources),
   108	        records: selected(maps.records, membership.records),
   109	        findings: selected(maps.findings, membership.findings),
   110	        themes: selected(maps.themes, membership.themes),
   111	        requirements: selected(maps.requirements, membership.requirements),
   112	      };
   113	    },
   114	    closure(layer: PrimaryLayer, id: string): Membership {
   115	      const membership = emptyMembership();
   116	      function add(key: DataKey, ref: string): void {
   117	        if (membership[key].has(ref)) return;
   118	        if (!maps[key].has(ref)) {
   119	          missing(key, ref);
   120	          return;
   121	        }
   122	        membership[key].add(ref);
   123	        switch (key) {
   124	          case "requirements": {
   125	            const requirement = maps.requirements.get(ref)!;
   126	            const findingIds = [...requirement.findingIds, ...requirement.conflictingFindingIds];
   127	            for (const findingId of findingIds) {
   128	              add("findings", findingId);
   129	              for (const themeId of themesByFinding.get(findingId) ?? []) add("themes", themeId);
   130	              const themeId = maps.findings.get(findingId)?.themeId;
   131	              if (themeId) add("themes", themeId);
   132	            }
   133	            for (const sourceId of requirement.sourceIds) add("sources", sourceId);
   134	            break;
   135	          }
   136	          case "themes": {
   137	            for (const findingId of maps.themes.get(ref)!.findingIds) add("findings", findingId);
   138	            for (const findingId of findingsByTheme.get(ref) ?? []) add("findings", findingId);
