    75	/** Semantic contract check is required even when a provider already validated the Zod schema. */
    76	export function validateIds<T extends { id: string }>(
    77	  items: T[],
    78	  expected: string[],
    79	): Map<string, T> {
    80	  const allowed = new Set(expected);
    81	  const byId = new Map<string, T>();
    82	  for (const item of items) {
    83	    if (!allowed.has(item.id))
    84	      throw new Error(`AI Splitter returned unknown assignment ID ${item.id}`);
    85	    if (byId.has(item.id))
    86	      throw new Error(`AI Splitter returned duplicate assignment ID ${item.id}`);
    87	    byId.set(item.id, item);
    88	  }
    89	  const missing = expected.filter((id) => !byId.has(id));
    90	  if (missing.length)
    91	    throw new Error(`AI Splitter is missing assignments for ${missing.join(", ")}`);
    92	  return byId;
    93	}
